package br.com.onda;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.widget.*;import androidx.core.content.FileProvider;import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;import com.tom_roush.pdfbox.pdmodel.*;import com.tom_roush.pdfbox.pdmodel.font.PDType1Font;import org.junit.*;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

public class DocumentConverterTest {
 private final android.app.Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private final ArrayList<File> garbage=new ArrayList<>();private DocumentConverterActivity activity;
 @After public void cleanup(){if(activity!=null)ins.runOnMainSync(()->activity.finish());for(File file:garbage)file.delete();}
 private File file(String ext)throws Exception{File f=new File(DocumentConverter.folder(c),"test-"+UUID.randomUUID()+ext);garbage.add(f);return f;}
 private Uri uri(File f){return FileProvider.getUriForFile(c,c.getPackageName()+".share",f);}
 private File convert(DocumentConverter.Mode mode,File...input)throws Exception{ArrayList<Uri> list=new ArrayList<>();for(File f:input)list.add(uri(f));File out=DocumentConverter.convert(c,list,mode,new LocalAiModels.Cancel(),(a,b)->{});garbage.add(out);return out;}
 private File photo(int color)throws Exception{File file=file(".png");Bitmap bitmap=Bitmap.createBitmap(1200,800,Bitmap.Config.ARGB_8888);new Canvas(bitmap).drawColor(color);try(OutputStream out=new FileOutputStream(file)){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}finally{bitmap.recycle();}return file;}
 private byte[] hash(File file)throws Exception{return MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file.toPath()));}
 private File pdf(boolean text)throws Exception{PDFBoxResourceLoader.init(c);File file=file(".pdf");try(PDDocument doc=new PDDocument()){for(int i=0;i<2;i++){PDPage page=new PDPage();doc.addPage(page);if(text)try(PDPageContentStream stream=new PDPageContentStream(doc,page)){stream.beginText();stream.setFont(PDType1Font.HELVETICA,14);stream.newLineAtOffset(40,700);stream.showText("Onda documento pagina "+(i+1));stream.endText();}}doc.save(file);}return file;}
 @Test public void photosBecomePdfAndEveryPageBecomesPngZipWithoutSourceChanges()throws Exception{File red=photo(Color.RED),green=photo(Color.GREEN);byte[] before=hash(red);File pdf=convert(DocumentConverter.Mode.IMAGES_PDF,red,green);try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(pdf,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){assertEquals(2,renderer.getPageCount());try(PdfRenderer.Page page=renderer.openPage(0)){assertTrue(page.getWidth()>page.getHeight());}}File zip=convert(DocumentConverter.Mode.PDF_IMAGES,pdf);try(ZipFile archive=new ZipFile(zip)){assertEquals(2,archive.size());for(int i=0;i<2;i++){ZipEntry entry=archive.getEntry(String.format(Locale.ROOT,"pagina-%04d.png",i+1));assertNotNull(entry);try(InputStream in=archive.getInputStream(entry)){Bitmap bitmap=BitmapFactory.decodeStream(in);assertNotNull(bitmap);assertEquals(1600,Math.max(bitmap.getWidth(),bitmap.getHeight()));int pixel=bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2);assertTrue(i==0?Color.red(pixel)>200&&Color.green(pixel)<30:Color.green(pixel)>200&&Color.red(pixel)<30);bitmap.recycle();}}}assertArrayEquals(before,hash(red));assertTrue(green.isFile());}
 @Test public void longUtf8TextIsPaginatedAndAccentsSurviveRoundTrip()throws Exception{File input=file(".txt");StringBuilder text=new StringBuilder();for(int i=0;i<300;i++)text.append("Linha ").append(i).append(" — Olá, coração e música do Onda.\n");Files.write(input.toPath(),text.toString().getBytes(StandardCharsets.UTF_8));byte[] before=hash(input);File pdf=convert(DocumentConverter.Mode.TEXT_PDF,input);try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(pdf,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){assertTrue(renderer.getPageCount()>3);}File output=convert(DocumentConverter.Mode.PDF_TEXT,pdf);String result=new String(Files.readAllBytes(output.toPath()),StandardCharsets.UTF_8);assertTrue(result,result.contains("Linha 0"));assertTrue(result,result.contains("Linha 299"));assertTrue(result,result.contains("coração"));assertArrayEquals(before,hash(input));}
 @Test public void docxReadsMainTextButDoesNotExecuteOrEmbedExternalContent()throws Exception{File docx=file(".docx");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(docx))){zip.putNextEntry(new ZipEntry("word/document.xml"));zip.write(("<?xml version=\"1.0\" encoding=\"UTF-8\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body><w:p><w:r><w:t>Primeiro parágrafo Onda</w:t></w:r></w:p><w:p><w:r><w:t>Segundo texto final</w:t></w:r></w:p></w:body></w:document>").getBytes(StandardCharsets.UTF_8));zip.closeEntry();}byte[] before=hash(docx);File pdf=convert(DocumentConverter.Mode.DOCX_PDF,docx),txt=convert(DocumentConverter.Mode.PDF_TEXT,pdf);String result=new String(Files.readAllBytes(txt.toPath()),StandardCharsets.UTF_8);assertTrue(result,result.contains("Primeiro parágrafo Onda"));assertTrue(result,result.contains("Segundo texto final"));assertArrayEquals(before,hash(docx));}
 @Test public void pdfTextExtractsAllPagesAndScanOnlyExplainsOcr()throws Exception{File input=pdf(true),txt=convert(DocumentConverter.Mode.PDF_TEXT,input);String text=new String(Files.readAllBytes(txt.toPath()),StandardCharsets.UTF_8);assertTrue(text.contains("pagina 1"));assertTrue(text.contains("pagina 2"));try{convert(DocumentConverter.Mode.PDF_TEXT,pdf(false));fail("Image-only PDF must explain OCR");}catch(IOException e){assertTrue(e.getMessage(),e.getMessage().contains("OCR"));}}
 @Test public void cancelledAndInvalidConversionsDoNotLeavePartialOutputs()throws Exception{File input=photo(Color.RED);Set<String> before=new HashSet<>(Arrays.asList(DocumentConverter.folder(c).list()));LocalAiModels.Cancel cancel=new LocalAiModels.Cancel();try{DocumentConverter.convert(c,Collections.nCopies(3,uri(input)),DocumentConverter.Mode.IMAGES_PDF,cancel,(n,total)->cancel.cancel());fail("Must stop");}catch(InterruptedIOException expected){}assertEquals(before,new HashSet<>(Arrays.asList(DocumentConverter.folder(c).list())));File invalid=file(".bin");Files.write(invalid.toPath(),new byte[]{0,1,2});try{convert(DocumentConverter.Mode.TEXT_PDF,invalid);fail("Binary input accepted");}catch(IOException expected){}try{convert(DocumentConverter.Mode.DOCX_PDF,invalid);fail("Invalid DOCX accepted");}catch(IOException expected){}}
 @Test public void protectedPdfDoesNotBypassExtractionPermission()throws Exception{File plain=pdf(true),input=file(".pdf");try(PDDocument doc=PDDocument.load(plain)){com.tom_roush.pdfbox.pdmodel.encryption.AccessPermission permission=new com.tom_roush.pdfbox.pdmodel.encryption.AccessPermission();permission.setCanExtractContent(false);doc.protect(new com.tom_roush.pdfbox.pdmodel.encryption.StandardProtectionPolicy("owner-secret","",permission));doc.save(input);}try{convert(DocumentConverter.Mode.PDF_TEXT,input);fail("Restricted PDF text was extracted");}catch(IOException expected){assertTrue(expected.getMessage(),expected.getMessage().contains("não permite"));}}
 @Test public void converterUiCreatesSharesAndSavesAnActualPdf()throws Exception{activity=(DocumentConverterActivity)ins.startActivitySync(new Intent(c,DocumentConverterActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();File input=photo(Color.BLUE);ins.runOnMainSync(()->activity.onActivityResult(9731,Activity.RESULT_OK,new Intent().setData(uri(input))));ins.runOnMainSync(()->{try{((Button)get("convert")).performClick();}catch(Exception e){throw new RuntimeException(e);}});long end=android.os.SystemClock.elapsedRealtime()+30000;while((Boolean)get("busy")&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(80);assertFalse((Boolean)get("busy"));File result=(File)get("result");assertNotNull(((TextView)get("status")).getText().toString(),result);garbage.add(result);try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(result,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){assertEquals(1,renderer.getPageCount());}Intent share=ImageSharing.send(c,result,"application/pdf",null);assertEquals("application/pdf",share.getType());assertNotNull(share.getClipData());File saved=file(".pdf");ins.runOnMainSync(()->activity.onActivityResult(9732,Activity.RESULT_OK,new Intent().setData(uri(saved))));while((Boolean)get("busy")&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(80);assertFalse((Boolean)get("busy"));assertArrayEquals(hash(result),hash(saved));assertTrue(((TextView)get("status")).getText().toString().contains("Cópia salva"));Bitmap screen=ins.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"document-converter.png"))){screen.compress(Bitmap.CompressFormat.PNG,100,out);}finally{screen.recycle();}}
 private Object get(String name)throws Exception{Field field=DocumentConverterActivity.class.getDeclaredField(name);field.setAccessible(true);return field.get(activity);}
}
